//! Build script: the platform setup `napi-build` provides for a NAPI addon.

fn main() {
    napi_build::setup();
}
2:name = "caliper-docgen-napi"
17:napi = { workspace = true, features = ["tokio_rt"] }
18:napi-derive.workspace  = true
27:napi-build = "2"
/opt/homebrew/bin/docker

